static class Phase7CTests
{
 const string Password="Fase7C-Isolada!123";static int count;
 static void Pass(bool ok,string label){if(!ok)throw new Exception("FAIL "+label);count++;Console.WriteLine("PASS "+label);}
 static void Sql(string file,string sql){using var c=new SqliteConnection($"Data Source={file};Pooling=False");c.Open();using var cmd=c.CreateCommand();cmd.CommandText=sql;cmd.ExecuteNonQuery();}
 static string Value(string file,string sql){using var c=new SqliteConnection($"Data Source={file};Mode=ReadOnly;Pooling=False");c.Open();using var cmd=c.CreateCommand();cmd.CommandText=sql;return cmd.ExecuteScalar()?.ToString()??"";}
 public static void Run(string folder,string snapshot)=>RunAsync(Path.GetFullPath(folder),Path.GetFullPath(snapshot)).GetAwaiter().GetResult();
 static async Task RunAsync(string folder,string snapshot){
  Directory.CreateDirectory(folder);var copyFolder=Path.Combine(folder,"migration");Directory.CreateDirectory(copyFolder);var copy=Path.Combine(copyFolder,"caixa_dados.db");File.Copy(snapshot,copy);
  var definitions=new Dictionary<string,string>();var before=new Dictionary<string,string>();
  using(var c=new SqliteConnection($"Data Source={copy};Mode=ReadOnly;Pooling=False")){c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name";using var r=cmd.ExecuteReader();var tables=new List<string>();while(r.Read())tables.Add(r.GetString(0));r.Close();foreach(var table in tables){cmd.CommandText=$"PRAGMA table_info(\"{table}\")";using var info=cmd.ExecuteReader();var columns=new List<string>();while(info.Read())columns.Add('"'+info.GetString(1)+'"');info.Close();definitions[table]=$"SELECT {string.Join(',',columns)} FROM \"{table}\" ORDER BY 1";}}
  string Fingerprint(string sql){using var c=new SqliteConnection($"Data Source={copy};Mode=ReadOnly;Pooling=False");c.Open();using var cmd=c.CreateCommand();cmd.CommandText=sql;using var r=cmd.ExecuteReader();using var hash=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);while(r.Read())hash.AppendData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(Enumerable.Range(0,r.FieldCount).Select(i=>r.IsDBNull(i)?null:r.GetValue(i) is byte[] b?Convert.ToHexString(b):r.GetValue(i).ToString()).ToArray())));return Convert.ToHexString(hash.GetHashAndReset());}
  foreach(var p in definitions)before[p.Key]=Fingerprint(p.Value);
  var migration=new IdentitySecurity(new DataStore(copyFolder,true));migration.Migrate();migration.Migrate();
  foreach(var p in definitions)Pass(before[p.Key]==Fingerprint(p.Value),"migração duas vezes preserva valores originais: "+p.Key);
  Pass(Value(copy,"SELECT COUNT(*) FROM auth_devices")=="0"&&Value(copy,"SELECT COUNT(*) FROM auth_pairings")=="0","migração não inventa dispositivos ou códigos");
  var data=new DataStore(Path.Combine(folder,"api"));data.EnsureInitialized();data.Update(d=>{d.Prompt12.LoginPassword=LoginSecurity.Create(Password);d.Prompt12.OwnerPin=OwnerSecurity.Create("917345");return 0;});var security=new IdentitySecurity(data);security.Migrate();
  var listener=System.Net.Sockets.TcpListener.Create(0);listener.Start();var port=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();
  await using var server=await SharedDataServer.StartAsync(data,Path.Combine(folder,"identity"),port,Path.Combine(folder,"logs"));var connection=server.Connection with {Url=$"https://127.0.0.1:{port}",Urls=null};
  HttpClient Client(string? device=null){var http=new HttpClient(new HttpClientHandler{ServerCertificateCustomValidationCallback=(_,cert,_,_)=>RemoteDataClient.CertificateMatchesPin(cert,connection.CertificatePin)}){BaseAddress=new Uri(connection.Url+"/")};if(device!=null)http.DefaultRequestHeaders.Add("X-Device-Key",device);return http;}
  async Task Expect(HttpResponseMessage response,HttpStatusCode status,string label){using(response)Pass(response.StatusCode==status,label+" HTTP "+(int)status);}
  async Task<SessionTokens> Login(HttpClient http,string user="grafica",string? password=null){using var response=await http.PostAsJsonAsync("auth/login",new{User=user,Password=password??Password,Role="Financeiro",UserId=Guid.NewGuid(),DeviceId=Guid.NewGuid()});Pass(response.IsSuccessStatusCode,"login com usuário real do servidor");var tokens=(await response.Content.ReadFromJsonAsync<SessionTokens>())!;http.DefaultRequestHeaders.Authorization=new("Bearer",tokens.AccessToken);return tokens;}
  using var anonymous=Client();foreach(var path in new[]{"data","auth/me","backups","devices","auth/sessions"})await Expect(await anonymous.GetAsync(path),HttpStatusCode.Unauthorized,"sem credencial "+path);
  using var legacy=Client(File.ReadAllText(Path.Combine(folder,"identity","chave-servidor.txt")).Trim());legacy.DefaultRequestHeaders.Authorization=new("Bearer",File.ReadAllText(Path.Combine(folder,"identity","chave-servidor.txt")).Trim());foreach(var path in new[]{"data","auth/me","health"})await Expect(await legacy.GetAsync(path),HttpStatusCode.Unauthorized,"chave global antiga recusada "+path);
  using var admin=Client(connection.Key);var owner=await Login(admin);Pass(owner.User.Role=="Administrador"&&owner.User.DeviceId==connection.DeviceId,"role e dispositivo falsos não alteram identidade");
  using(var response=await admin.PostAsync("devices/pairings",null)){Pass(response.IsSuccessStatusCode,"Administrador cria pareamento temporário");var ticket=(await response.Content.ReadFromJsonAsync<PairingTicket>())!;Pass(ticket.ExpiresAt>DateTimeOffset.UtcNow&&ticket.ExpiresAt<DateTimeOffset.UtcNow.AddMinutes(11),"pareamento expira em dez minutos");
   using var pair=await anonymous.PostAsJsonAsync("devices/pair",new PairDeviceRequest(ticket.Ticket,"PC2 de teste"));Pass(pair.IsSuccessStatusCode,"pareamento emite credencial exclusiva");var device=(await pair.Content.ReadFromJsonAsync<DeviceCredential>())!;Pass(device.Secret!=connection.Key,"dispositivos não compartilham chave");
   await Expect(await anonymous.PostAsJsonAsync("devices/pair",new PairDeviceRequest(ticket.Ticket,"Captura reutilizada")),HttpStatusCode.Unauthorized,"código de captura não reutilizável");
   using var pc2=Client(device.Secret);await Expect(await pc2.GetAsync("data"),HttpStatusCode.Unauthorized,"dispositivo pareado não autentica usuário");
   pc2.DefaultRequestHeaders.Authorization=new("Bearer",owner.AccessToken);await Expect(await pc2.GetAsync("data"),HttpStatusCode.Unauthorized,"token não pode migrar para outro dispositivo");
   await Expect(await pc2.PostAsJsonAsync("auth/refresh",new RefreshRequest(owner.RefreshToken)),HttpStatusCode.Unauthorized,"refresh de outro dispositivo recusado");
   var session=await Login(pc2);using(var me=await pc2.GetAsync("auth/me")){var user=(await me.Content.ReadFromJsonAsync<UserIdentity>())!;Pass(user.UserId==owner.User.UserId&&user.DeviceId==device.Id,"identidade real vinculada ao PC2 de teste");}
   Sql(data.DatabasePath,$"UPDATE auth_sessions SET access_expires=0 WHERE id='{session.User.SessionId}'");await Expect(await pc2.GetAsync("data"),HttpStatusCode.Unauthorized,"sessão expirada exige refresh");
   using var renewedResponse=await pc2.PostAsJsonAsync("auth/refresh",new RefreshRequest(session.RefreshToken));Pass(renewedResponse.IsSuccessStatusCode,"refresh válido restaura sessão");var renewed=(await renewedResponse.Content.ReadFromJsonAsync<SessionTokens>())!;Pass(renewed.AccessToken!=session.AccessToken&&renewed.RefreshToken!=session.RefreshToken,"refresh rotaciona os dois tokens");
   pc2.DefaultRequestHeaders.Authorization=new("Bearer",renewed.AccessToken);await Expect(await pc2.GetAsync("data"),HttpStatusCode.OK,"requisição renovada autorizada");
   await Expect(await pc2.PostAsJsonAsync("auth/refresh",new RefreshRequest(session.RefreshToken)),HttpStatusCode.Unauthorized,"refresh reutilizado recusado");await Expect(await pc2.GetAsync("data"),HttpStatusCode.Unauthorized,"replay revoga família da sessão");
   session=await Login(pc2);await Expect(await admin.PostAsJsonAsync("auth/sessions/end",new SessionEnd(session.User.SessionId)),HttpStatusCode.OK,"Administrador encerra sessão específica");await Expect(await pc2.GetAsync("data"),HttpStatusCode.Unauthorized,"sessão encerrada não reutiliza access");
   session=await Login(pc2);await Expect(await admin.PostAsJsonAsync("devices/revoke",new DeviceRevoke(device.Id)),HttpStatusCode.OK,"Administrador revoga dispositivo");await Expect(await pc2.GetAsync("data"),HttpStatusCode.Unauthorized,"dispositivo revogado perde acesso imediatamente");await Expect(await pc2.PostAsJsonAsync("auth/refresh",new RefreshRequest(session.RefreshToken)),HttpStatusCode.Unauthorized,"dispositivo revogado não renova");
  }
  var expiring=security.CreatePairing(owner.User,"teste");Sql(data.DatabasePath,"UPDATE auth_pairings SET expires_at=0 WHERE consumed_at IS NULL");await Expect(await anonymous.PostAsJsonAsync("devices/pair",new PairDeviceRequest(expiring.Ticket,"Expirado")),HttpStatusCode.Unauthorized,"ticket expirado recusado");
  var canceled=security.CreatePairing(owner.User,"teste");await Expect(await admin.PostAsync("devices/pairings/revoke",null),HttpStatusCode.OK,"revogação de tickets pendentes");await Expect(await anonymous.PostAsJsonAsync("devices/pair",new PairDeviceRequest(canceled.Ticket,"Revogado")),HttpStatusCode.Unauthorized,"ticket revogado recusado");
  using var other=Client(connection.Key);var logout=await Login(other);await Expect(await other.PostAsync("auth/logout",null),HttpStatusCode.OK,"logout real");await Expect(await other.GetAsync("data"),HttpStatusCode.Unauthorized,"token antigo após logout negado");await Expect(await other.PostAsJsonAsync("auth/refresh",new RefreshRequest(logout.RefreshToken)),HttpStatusCode.Unauthorized,"refresh antigo após logout negado");
  await Expect(await admin.PostAsJsonAsync("auth/users",new UserEdit(null,"Financeiro","financeiro","Financeiro",true,Password)),HttpStatusCode.OK,"usuário 7B reutilizado");var employee=await Login(other,"financeiro");await Expect(await other.GetAsync("devices"),HttpStatusCode.Forbidden,"usuário sem autorização administrativa negado");
  security.SavePermissions(owner.User,new(employee.User.UserId,null,new(){["system.backups"]=true}),"teste");await Expect(await other.PostAsJsonAsync("restore",new RestoreRequest("inexistente")),HttpStatusCode.Forbidden,"restore exige Administrador mesmo com permissão delegada");
  await Expect(await other.PostAsync("devices/rotate",null),HttpStatusCode.Forbidden,"Financeiro não rotaciona a credencial do dispositivo compartilhado");
  await Expect(await admin.PostAsJsonAsync("auth/users",new UserEdit(employee.User.UserId,"Financeiro","financeiro","Financeiro",false,null)),HttpStatusCode.OK,"desativação 7B preservada");await Expect(await other.GetAsync("data"),HttpStatusCode.Unauthorized,"token após desativação negado");
  await Expect(await admin.PostAsJsonAsync("auth/users",new UserEdit(employee.User.UserId,"Financeiro","financeiro","Financeiro",true,Password)),HttpStatusCode.OK,"reativação para teste de reset");employee=await Login(other,"financeiro");await Expect(await admin.PostAsJsonAsync("auth/users",new UserEdit(employee.User.UserId,"Financeiro","financeiro","Financeiro",true,"Reset7C-Teste!123")),HttpStatusCode.OK,"reset de senha");await Expect(await other.GetAsync("data"),HttpStatusCode.Unauthorized,"reset invalida tokens anteriores");
  var client=new RemoteDataClient(connection);Pass(client.VerifyLogin("grafica",Password).Ok,"WPF usa login individual");Pass(new RemoteDataClient(connection).ResumeSession(),"WPF retoma sessão DPAPI sem repetir senha");
  var last=new RemoteDataClient(connection);Pass(last.ResumeSession(),"refresh rotacionado persistido pode retomar novamente");last.Logout();Pass(!new RemoteDataClient(connection).ResumeSession(),"logout apaga sessão local cifrada");
  var fake=owner.AccessToken[..63]+(owner.AccessToken[63]=='0'?'1':'0');other.DefaultRequestHeaders.Authorization=new("Bearer",fake);await Expect(await other.GetAsync("data"),HttpStatusCode.Unauthorized,"credencial adulterada negada");
  var backup=data.ListBackups().First().Path;var users=Value(data.DatabasePath,"SELECT COUNT(*) FROM auth_users");var devices=Value(data.DatabasePath,"SELECT COUNT(*) FROM auth_devices");await Expect(await admin.PostAsJsonAsync("restore",new RestoreRequest(backup)),HttpStatusCode.OK,"restore drill somente na base isolada");Pass(users==Value(data.DatabasePath,"SELECT COUNT(*) FROM auth_users")&&devices==Value(data.DatabasePath,"SELECT COUNT(*) FROM auth_devices"),"restore preserva usuários e dispositivos correntes");
  Pass(Value(data.DatabasePath,"SELECT COUNT(*) FROM audit_trail WHERE action='Backup restaurado' AND user_id<>'' AND session_id<>''")!="0","restore auditado pela identidade real");
  using var rotation=await admin.PostAsync("devices/rotate",null);Pass(rotation.IsSuccessStatusCode,"rotação de credencial individual");var rotated=(await rotation.Content.ReadFromJsonAsync<DeviceCredential>())!;await Expect(await admin.GetAsync("data"),HttpStatusCode.Unauthorized,"credencial antiga deixa de funcionar após rotação");using var fresh=Client(rotated.Secret);await Login(fresh);await Expect(await fresh.GetAsync("data"),HttpStatusCode.OK,"nova credencial funciona com novo login");
  var secrets=new[]{owner.AccessToken,owner.RefreshToken,connection.Key,rotated.Secret,Password};var audit=string.Join('\n',data.Load().AuditTrail.Select(x=>JsonSerializer.Serialize(x)));var logs=string.Join('\n',Directory.GetFiles(Path.Combine(folder,"logs"),"*",SearchOption.AllDirectories).Select(File.ReadAllText));Pass(secrets.All(x=>!audit.Contains(x)&&!logs.Contains(x)),"auditoria e logs não contêm segredos");
  var now=DateTimeOffset.UtcNow;var timed=new IdentitySecurity(data,()=>now);var dev=timed.BootstrapDevice("Relógio isolado","teste");var absolute=timed.Login("grafica",Password,"clock",dev.Id)!;Pass(absolute.ExpiresAt<=now.AddMinutes(16)&&absolute.RefreshExpiresAt<=now.AddDays(8)&&absolute.AbsoluteExpiresAt<=now.AddDays(31),"política 15 minutos / 7 dias / 30 dias");now=now.AddDays(8);Pass(timed.Refresh(absolute.RefreshToken,"clock",dev.Id)==null,"inatividade expira refresh");
  now=DateTimeOffset.UtcNow;absolute=timed.Login("grafica",Password,"clock2",dev.Id)!;for(var i=0;i<6;i++){now=now.AddDays(5);if(i<5)absolute=timed.Refresh(absolute.RefreshToken,"clock2",dev.Id)!;else Pass(timed.Refresh(absolute.RefreshToken,"clock2",dev.Id)==null,"renovações não ultrapassam limite absoluto de trinta dias");}
  Console.WriteLine($"PHASE7C PASSED: {count} verificações; ambiente isolado; testes físicos remotos pendentes.");
 }
}
